const first = $input.first().json;

function fail(msg) {
  throw new Error('LLM output validation failed: ' + msg);
}

let out = first.output ?? first.text ?? first;
if (typeof out === 'string') {
  const cleaned = out.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try {
    out = JSON.parse(cleaned);
  } catch (e) {
    fail('model did not return valid JSON: ' + e.message);
  }
}

if (typeof out !== 'object' || out === null) fail('output is not an object');
if (typeof out.executive_summary !== 'string' || out.executive_summary.trim() === '')
  fail('executive_summary missing or empty');
if (!Array.isArray(out.high_priority_items)) fail('high_priority_items is not an array');
if (!Array.isArray(out.blocked_items)) fail('blocked_items is not an array');
if (!Array.isArray(out.recommendations) || out.recommendations.length === 0)
  fail('recommendations missing or empty');

for (const it of out.high_priority_items) {
  if (!it.item_id || !it.feature || !it.why_it_matters)
    fail('a high_priority_item is missing item_id/feature/why_it_matters');
}
for (const it of out.blocked_items) {
  if (!it.item_id || !it.feature || !it.blocker || !it.suggested_action)
    fail('a blocked_item is missing item_id/feature/blocker/suggested_action');
}

// Cross-check against deterministic counts — the LLM must not add or drop items
const counts = $('Validate + Count').first().json;
if (out.high_priority_items.length !== counts.highCount)
  fail(`LLM listed ${out.high_priority_items.length} high items, deterministic count is ${counts.highCount}`);
if (out.blocked_items.length !== counts.blockedCount)
  fail(`LLM listed ${out.blocked_items.length} blocked items, deterministic count is ${counts.blockedCount}`);

return [{ json: out }];

const digest = $input.first().json;
const counts = $('Validate + Count').first().json;

// ---- CONFIG (hardcoded here for the demo; in production these belong in n8n Static
//      Data or environment variables, not the Code node). Base/table id are the
//      appXXXX/tblXXXX parts of the Airtable URL. -----------------------------------
const AIRTABLE_BASE = 'appeluaViGRDZJKDQ';
const AIRTABLE_TABLE = 'tbl5oMK0fmzpVHCtW';
// Owner -> Slack member id. In production this is a lookup table (Static Data / a Config
// node). The sample roadmap's owners are fictional, so one is mapped to a real member id
// for the demo; unmapped owners fall back to their plain name.
const OWNER_SLACK_IDS = {
  'Ravi T': 'U0BEYUAAAHG',
};

const byId = {};
for (const r of counts.records) byId[r.itemId] = r;

const linkable = AIRTABLE_BASE.startsWith('app') && !AIRTABLE_BASE.includes('XXXX');
function link(itemId, feature) {
  const rec = byId[itemId];
  return linkable && rec && rec.recordId
    ? `<https://airtable.com/${AIRTABLE_BASE}/${AIRTABLE_TABLE}/${rec.recordId}|${feature}>`
    : feature;
}
function ownerTag(owner) {
  return OWNER_SLACK_IDS[owner] ? `<@${OWNER_SLACK_IDS[owner]}>` : (owner || '—');
}

const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: '📋 Daily Roadmap Digest', emoji: true } });
blocks.push({
  type: 'context',
  elements: [{
    type: 'mrkdwn',
    text: `*${counts.recordCount}* items  •  🔥 *${counts.highCount}* High priority  •  ⛔ *${counts.blockedCount}* Blocked  •  🕒 *${counts.staleCount}* stale`,
  }],
});
blocks.push({ type: 'divider' });

blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Executive Summary*\n${digest.executive_summary}` } });

// High priority
blocks.push({ type: 'divider' });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*🔥 High Priority (${counts.highCount})*` } });
digest.high_priority_items.forEach((it, i) => {
  const rec = byId[it.item_id];
  const staleFlag = rec && rec.stale ? '  🕒 _stale_' : '';
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${i + 1}. ${link(it.item_id, it.feature)}*  (\`${it.item_id}\` • ${it.owner || '—'} • ${it.target_quarter || '—'})${staleFlag}\n${it.why_it_matters}`,
    },
  });
});

// Blocked — @-mention the actual owner (accountability, not just broadcast)
if (digest.blocked_items.length > 0) {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*⛔ Blocked (${counts.blockedCount})*` } });
  digest.blocked_items.forEach((it) => {
    blocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${link(it.item_id, it.feature)}*  (\`${it.item_id}\` • ${ownerTag(it.owner)})\nBlocker: ${it.blocker}\n➡️ ${it.suggested_action}`,
      },
    });
  });
}

// Recommendations
blocks.push({ type: 'divider' });
blocks.push({
  type: 'section',
  text: { type: 'mrkdwn', text: `*✅ Recommendations*\n${digest.recommendations.map((r) => `•  ${r}`).join('\n')}` },
});

// Footer
const dist = Object.entries(counts.statusDistribution).map(([k, v]) => `${k}: *${v}*`).join('   |   ');
let footer = `Generated ${counts.runTimestamp}`;
if (counts.skippedCount > 0) footer += `  •  ⚠️ ${counts.skippedCount} invalid record(s) skipped`;
blocks.push({ type: 'divider' });
blocks.push({ type: 'context', elements: [
  { type: 'mrkdwn', text: `Status — ${dist}` },
  { type: 'mrkdwn', text: footer },
] });

return [{
  json: {
    blocks,
    blocksJson: JSON.stringify({ blocks }),
    highCount: counts.highCount,
    blockedCount: counts.blockedCount,
    notificationText: `Daily Roadmap Digest — ${counts.highCount} High priority, ${counts.blockedCount} Blocked`,
  },
}];

const j = $input.first().json;

const blocks = [
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `<!here> *${j.highCount} items are High priority — attention needed.*`,
    },
  },
  ...j.blocks,
];

return [
  {
    json: {
      ...j,
      blocks,
      blocksJson: JSON.stringify({ blocks }),
      notificationText: `@here ${j.notificationText}`,
    },
  },
];

const REQUIRED = ['Feature', 'Priority', 'Status', 'Owner'];
const KNOWN_PRIORITIES = ['high', 'medium', 'low'];
const KNOWN_STATUSES = ['in progress', 'not started', 'blocked'];
const STALE_DAYS = 14; // not updated in this many days => "stale"

const items = $input.all();
if (items.length === 0) {
  throw new Error('Airtable returned 0 records — aborting digest run.');
}

const now = new Date();

// Robust date parsing: accepts YYYY-MM-DD (Airtable/ISO) and DD-MM-YYYY / DD/MM/YYYY.
function daysSince(dateStr) {
  if (!dateStr) return null;
  const s = String(dateStr).trim();
  let d;
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    d = new Date(s);
  } else {
    const m = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);
    d = m ? new Date(`${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`) : new Date(s);
  }
  return isNaN(d) ? null : Math.floor((now - d) / 86400000);
}

const valid = [];
const skipped = [];

for (const item of items) {
  const raw = item.json;
  const f = raw.fields ?? raw; // Airtable v1 nests under "fields", v2 flattens

  const missing = REQUIRED.filter(
    (k) => f[k] === undefined || f[k] === null || String(f[k]).trim() === ''
  );
  if (missing.length > 0) {
    skipped.push({ itemId: f['Item ID'] ?? raw.id ?? 'unknown', reason: 'missing: ' + missing.join(', ') });
    continue;
  }

  // Normalize once, validate against known enums — tolerant of case/whitespace typos.
  const priorityKey = String(f['Priority']).trim().toLowerCase();
  const statusKey = String(f['Status']).trim().toLowerCase();
  if (!KNOWN_PRIORITIES.includes(priorityKey)) {
    skipped.push({ itemId: f['Item ID'] ?? raw.id, reason: `unknown priority "${f['Priority']}"` });
    continue;
  }
  if (!KNOWN_STATUSES.includes(statusKey)) {
    skipped.push({ itemId: f['Item ID'] ?? raw.id, reason: `unknown status "${f['Status']}"` });
    continue;
  }

  const lastUpdated = f['Last Updated'] ?? '';
  const days = daysSince(lastUpdated);
  valid.push({
    itemId: f['Item ID'] ?? raw.id,
    recordId: raw.id ?? '', // Airtable rec... id, for deep links in Build Slack Blocks
    feature: f['Feature'],
    status: f['Status'], // original casing for display
    statusKey, // normalized for logic
    priority: f['Priority'],
    priorityKey, // normalized for logic
    owner: f['Owner'],
    targetQuarter: f['Target Quarter'] ?? '',
    description: f['Description'] ?? '',
    lastUpdated,
    daysSinceUpdate: days,
    stale: days !== null && days > STALE_DAYS,
  });
}

if (valid.length === 0) {
  throw new Error('All records failed field validation — aborting digest run.');
}

const highItems = valid.filter((r) => r.priorityKey === 'high');
const blockedItems = valid.filter((r) => r.statusKey === 'blocked');
const staleItems = valid.filter((r) => r.stale);
const highCount = highItems.length;

const statusDistribution = {};
for (const r of valid) statusDistribution[r.status] = (statusDistribution[r.status] ?? 0) + 1;

return [
  {
    json: {
      records: valid,
      recordCount: valid.length,
      skippedCount: skipped.length,
      skipped,
      highCount,
      blockedCount: blockedItems.length,
      blockedIds: blockedItems.map((r) => r.itemId),
      staleCount: staleItems.length,
      staleIds: staleItems.map((r) => r.itemId),
      statusDistribution,
      mentionHere: highCount > 5, // deterministic @here decision
      runTimestamp: now.toISOString(),
    },
  },
];

